public static Stack<Integer> copy(Stack<Integer> s) {
    Stack<Integer> temp = new Stack<Integer>();
    Stack<Integer> result = new Stack<Integer>();
    while (!s.isEmpty()) {
        temp.push(s.pop());
    }
    // מחזירים לשתי המחסניות — כך שתיהן באותו סדר
    while (!temp.isEmpty()) {
        int x = temp.pop();
        s.push(x);
        result.push(x);
    }
    return result;
}

public static int countGreater(Stack<Integer> s, int x) {
    Stack<Integer> temp = new Stack<Integer>();
    int count = 0;
    while (!s.isEmpty()) {
        int y = s.pop();
        if (y > x) {
            count++;
        }
        temp.push(y);
    }
    // מחזירים את האיברים — המחסנית חוזרת להיות כמו בהתחלה
    while (!temp.isEmpty()) {
        s.push(temp.pop());
    }
    return count;
}

