Stack<Integer> s = new Stack<Integer>();
s.push(5);
s.push(8);
s.push(3);
Stack<Integer> c = copy(s);
System.out.println("סעיף א: " + c + " המקורית: " + s);
System.out.println("סעיף ב: " + countGreater(s, 4));
